WITH rows AS MATERIALIZED(SELECT v.session_date,v.company_ordinal,v.company_id,v.point_source_state,v.source_presence_state,encode(sha256(convert_to(to_jsonb(v)::text,'UTF8')),'hex')consumer_sha256,(v.regular_session_basis_verified IS FALSE AND v.corporate_action_qualified IS FALSE AND v.independent_economic_accuracy_verified IS FALSE AND v.original_historical_receipt_verified IS FALSE AND v.strict_point_in_time_qualified IS FALSE AND v.full_period_lifecycle_qualified IS FALSE AND v.family_accepted IS FALSE AND v.preliminary IS TRUE AND v.full_applicable_instrument_expected_units IS NULL AND v.overlay_manifest_sha256='__GRID_SHA256__')IS TRUE flags_ok FROM population_top3000_202608_202609_v1.working_d02_dated_source_points_v2 v),
dates AS MATERIALIZED(SELECT session_date,count(*)n,count(DISTINCT company_ordinal)ordinals,count(DISTINCT company_id)companies,min(company_ordinal)first_ordinal,max(company_ordinal)last_ordinal,encode(sha256(convert_to(string_agg(consumer_sha256,E'\n'ORDER BY company_ordinal),'UTF8')),'hex')consumer_row_sha_manifest FROM rows GROUP BY session_date),
checkpoints AS MATERIALIZED(SELECT c.*,jsonb_build_object('date',session_date,'source_day_id',source_day_id,'rows',rows,'value_manifest_sha256',value_manifest_sha256,'point_set_manifest_sha256',point_set_manifest_sha256,'source_pin',source_pin,'calendar_pin',calendar_pin,'source_proof',source_proof,'state_counts',state_counts,'assignment_event_id',assignment_event_id,'claim_event_id',claim_event_id)payload FROM population_top3000_202608_202609_v1.d02_anchor_source_checkpoint_v2 c),
checked AS MATERIALIZED(SELECT population_top3000_202608_202609_v1.ctx06_aug03_check_v5((SELECT count(*)FROM rows)=126000 AND(SELECT bool_and(flags_ok)FROM rows)IS TRUE AND(SELECT count(*)FROM dates)=42 AND NOT EXISTS(SELECT 1 FROM dates WHERE n<>3000 OR ordinals<>3000 OR companies<>3000 OR first_ordinal<>1 OR last_ordinal<>3000)AND(SELECT count(*)FROM checkpoints)=42 AND NOT EXISTS(SELECT 1 FROM checkpoints WHERE checkpoint_sha256 IS DISTINCT FROM encode(sha256(convert_to(payload::text,'UTF8')),'hex')),'D02_EXPORT_ACTIVATED_WHOLE_GRID_MANIFEST')ok)
SELECT jsonb_build_object('kind','D02_ACTIVATED_CONSUMER_INDEPENDENT_SERVER_MANIFEST_V1','consumer','population_top3000_202608_202609_v1.working_d02_dated_source_points_v2','row_count',126000,'date_count',42,'view_sha256','__VIEW_SHA256__','overlay_manifest_sha256','__GRID_SHA256__','ordered_consumer_row_sha_manifest',(SELECT encode(sha256(convert_to(string_agg(consumer_sha256,E'\n'ORDER BY session_date,company_ordinal),'UTF8')),'hex')FROM rows),'dates',(SELECT jsonb_agg(to_jsonb(d)ORDER BY session_date)FROM dates d),'completion_canonical_text',(SELECT to_jsonb(c)::text FROM population_top3000_202608_202609_v1.d02_anchor_source_completion_v2 c WHERE singleton),'checkpoints',(SELECT jsonb_agg(jsonb_build_object('checkpoint_canonical_text',(to_jsonb(c)-'payload')::text,'checkpoint_payload_text',payload::text,'checkpoint_sha256',checkpoint_sha256)ORDER BY session_date)FROM checkpoints c),'point_source_state_counts',(SELECT jsonb_object_agg(point_source_state,n)FROM(SELECT point_source_state,count(*)n FROM rows GROUP BY point_source_state)x),'source_presence_state_counts',(SELECT jsonb_object_agg(source_presence_state,n)FROM(SELECT source_presence_state,count(*)n FROM rows GROUP BY source_presence_state)x),'qualification','DATED_ANCHOR_POINT_AND_RETAINED_SOURCE_VALUE_LINK_ONLY_NOT_FINAL_FAMILY_OR_INSTRUMENT_CERTIFICATION')export FROM checked WHERE checked.ok;COMMIT;
